import {banks} from './banks.js';
import {KEY,blank,validate,rows,summary,debtRows,priorities,pay,edit,incomeRows,editIncome,deleteExpense,deleteIncome,months,addMonths,today,money,monthLabel} from './engine.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',wallet:'M3 5h16v15H3z M3 5V3h14 M15 10h6v5h-6z',chart:'M4 20V11 M10 20V4 M16 20V8 M22 20H2',spark:'m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7Z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',plus:'M12 5v14 M5 12h14',check:'m5 12 4 4L19 6',arrow:'M5 12h14 M14 7l5 5-5 5',down:'M12 3v12 m-5-5 5 5 5-5 M4 17v4h16v-4',home:'m3 10 9-7 9 7 M5 9v12h14V9 M9 21v-8h6v8',card:'M3 5h18v14H3z M3 10h18 M6 15h3',calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4',alert:'m12 3 10 18H2Z M12 9v5 M12 17v1',close:'m6 6 12 12 M6 18 18 6',up:'M6 16 18 4 M6 4h12v12',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z m-4 9 3 3 5-6'};
const icon=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.wallet}"/></svg>`;
let state=blank(),month=today().slice(0,7),view='overview',filter='all',search='',aiAvailable=false,aiText='',storageError=false;
let persisted=false;try{const raw=localStorage.getItem(KEY);if(raw){state=validate(JSON.parse(raw));persisted=true}}catch(e){storageError=true}
if(!persisted&&!storageError){try{const r=await fetch('./private-seed.json');if(r.ok){state=validate(await r.json());save(false)}}catch{}}
try{const r=await fetch('./api/status');if(r.ok)aiAvailable=!!(await r.json()).ai}catch{}
function save(notify=true){state.updatedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state));storageError=false;if(notify)toast('Kaydedildi')}catch{storageError=true;toast('Bu cihaz kayıt yapamıyor. Yedeğinizi indirin.')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3300)}
const nav=[['overview','grid','Genel bakış'],['payments','calendar','Ödemeler'],['debts','wallet','Borçlarım'],['plan','spark','Akıllı plan'],['reports','chart','Raporlar'],['settings','settings','Ayarlar']];
function navs(mobile=false){return nav.filter(x=>!mobile||x[0]!=='reports').map(([v,i,n])=>`<button class="${mobile?'':'nav-btn'} ${view===v?'active':''}" data-view="${v}" ${view===v?'aria-current="page"':''}>${icon(i)}<span>${n}</span></button>`).join('')}
function monthbar(){const start=addMonths(month,-2);return `<div class="monthbar"><button class="arrow" data-month="${addMonths(month,-1)}" aria-label="Önceki ay">‹</button><div class="months">${months(start,10).map(m=>`<button class="${m===month?'active':''}" data-month="${m}" aria-label="${monthLabel(m)}">${monthLabel(m)}</button>`).join('')}</div><button class="arrow" data-month="${addMonths(month,1)}" aria-label="Sonraki ay">›</button></div>`}
function render(){const s=summary(state,month);$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><img src="icon.svg" alt=""><div>pusula<small>KİŞİSEL FİNANS</small></div></div><div class="side-label">ÇALIŞMA ALANINIZ</div><nav>${navs()}</nav><div class="sidebar-bottom"><div class="side-note"><strong>${icon('shield').replace('<svg','<svg style="width:15px;vertical-align:middle"')} Kontrol sizde.</strong>Finansal kararlarınız, tek bir yerde. Her ay biraz daha net.</div><div class="profile"><span class="avatar">K</span><div><strong>Kişisel hesabım</strong><small>Cihazda saklanan veriler</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Çalışma alanı <span style="margin:0 10px">/</span> <b style="color:#536b58">${nav.find(x=>x[0]===view)[2]}</b></div><div class="topbar-right"><span class="saved"><i class="dot"></i>${storageError?'Kayıt sorunu':'Cihazda kayıtlı'}</span><button class="secondary" data-action="export">${icon('down')} Yedek al</button></div></header><div class="intro"><div><div class="eyebrow">PUSULA · KİŞİSEL FİNANS</div><h1>${({overview:'Finansal hayatınız, bir arada.',payments:'Her ödeme, yerli yerinde.',debts:'Borçlarınız netleşsin.',plan:'Bir sonraki doğru adım.',reports:'Büyük resmi görün.',settings:'Size göre bir düzen.'})[view]}</h1><p>${({overview:'Her ay daha net. Her ödeme kontrolünüzde.',payments:'Bir dokunuşla ödeyin. Kalan tutar anında güncellensin.',debts:'Kartlarınız ve kredi taksitleriniz, ayrı ve anlaşılır.',plan:'Öncelikleri görün, bütçenize göre plan yapın.',reports:'Aylık nakit akışınız ve borçlarınızın görünümü.',settings:'Gelir aralığınızı, kayıtlarınızı ve tercihlerinizi yönetin.'})[view]}</p></div>${view!=='settings'?`<button class="primary" data-action="new">${icon('plus')} Yeni ödeme</button>`:''}</div>${storageError?'<div class="error-banner">Kayıt okunamadı veya yazılamadı. Mevcut yedeğinizi koruyun; Ayarlar’dan geri yükleyebilirsiniz.</div>':''}${view!=='settings'?monthbar():''}${view==='overview'?overview(s):view==='payments'?payments(s):view==='debts'?debts():view==='plan'?plan(s):view==='reports'?reports():settings()}</main><nav class="mobilebar" aria-label="Ana menü">${navs(true)}</nav></div>`;const inp=$('#expense-search');if(inp)inp.value=search;}
function stats(s){const ds=debtRows(state,month),rr=rows(state,month),card=ds.filter(d=>d.type==='Kart').reduce((a,d)=>a+(d.remaining||0),0),loan=ds.filter(d=>d.type==='Kredi').reduce((a,d)=>a+(d.remaining||0),0),dueCard=rr.filter(r=>r.type==='Kart').reduce((a,r)=>a+r.remaining,0),dueLoan=rr.filter(r=>r.type==='Kredi').reduce((a,r)=>a+r.remaining,0);return `<section class="summary-shell" aria-label="Finans özeti"><div class="summary-caption"><span>${monthLabel(month)} · AYLIK ÖZET</span><span>${s.done} / ${s.count} ödeme tamamlandı</span></div><div class="stats"><div class="stat feature"><div class="stat-top">Bu ay kalan ödeme ${icon('wallet')}</div><div class="metric" data-testid="remaining">${money(s.remaining)}</div><small>Toplam gider: ${money(s.total)}</small><div class="progress"><i style="width:${Math.min(100,s.paid/Math.max(1,s.total)*100)}%"></i></div></div><div class="stat"><div class="stat-top">Bu ay ödediğim ${icon('check')}</div><div class="metric">${money(s.paid)}</div><small>${s.count-s.done} ödeme bekliyor</small></div><div class="stat"><div class="stat-top">Aylık gelir bütçesi ${icon('up')}</div><div class="metric">${money(s.base)}</div><small><button class="text-btn" data-action="income">Gelir bütçesini düzenle</button></small></div><div class="stat"><div class="stat-top">Gelir / gider farkı ${icon('chart')}</div><div class="metric ${s.baseGap<0?'red-text':''}">${money(s.baseGap)}</div><small>${s.baseGap<0?'Giderler için ek kaynak gerekiyor':'Gelir bütçesi giderleri karşılıyor'}</small></div></div><div class="debt-summary"><div><span>TOPLAM BİLİNEN BORÇ</span><strong>${money(card+loan)}</strong><small>Kart + kalan kredi taksitleri</small></div><div><span>KREDİ KARTI BORCU</span><strong>${money(card)}</strong><small>Bu ay kalan kart ödemesi: ${money(dueCard)}</small></div><div><span>KALAN KREDİ TAKSİTLERİ</span><strong>${money(loan)}</strong><small>Bu ay kalan kredi ödemesi: ${money(dueLoan)}</small></div></div><div class="summary-bottom"><span>Beklenen ek gelir: <b>${money(s.expected)}</b></span><span>Tahsil edilen: <b>${money(s.received)}</b></span><button class="text-btn" data-view="debts">Borç detayları ↗</button></div></section>`}

function empty(){return `<div class="empty-state"><h3>Yeni bir başlangıç.</h3>İlk ödemenizi ekleyin veya kişisel yedeğinizi yükleyin.<br><button class="primary" data-action="new">${icon('plus')} Ödeme ekle</button> <button class="secondary" data-action="import">Yedek yükle</button></div>`}
function expenseRows(rr){if(!rr.length)return `<div class="empty-state">Bu görünümde ödeme bulunmuyor.</div>`;return rr.map(r=>`<div class="expense-row ${r.isPaid?'done':''}"><button class="check ${r.isPaid?'checked':''}" role="checkbox" aria-checked="${r.isPaid}" aria-label="${esc(r.name)} ödendi" data-pay="${r.id}">${r.isPaid?icon('check'):''}</button><div class="expense-icon">${brandLogo(r)}</div><div class="expense-name"><strong>${esc(r.name)}</strong><small>${esc(r.type)}${r.count?' · '+(Number(month.slice(0,4))*12+Number(month.slice(5,7))-(Number(r.start.slice(0,4))*12+Number(r.start.slice(5,7)))+1)+' / '+r.count+' taksit':''}${r.paid&&!r.isPaid?' · '+money(r.paid)+' ödendi':''}</small></div><div class="due">${r.day?String(r.day).padStart(2,'0')+' '+new Date(month+'-15').toLocaleDateString('tr-TR',{month:'short'}):'Tarihsiz'}</div><div class="amount">${money(r.amount)}</div><button class="more" aria-label="${esc(r.name)} düzenle" data-edit="${r.id}">Düzenle</button></div>`).join('')}
function expensePanel(s,limit=0){let rr=rows(state,month).filter(r=>filter==='all'||(filter==='paid'?r.isPaid:!r.isPaid));if(search)rr=rr.filter(r=>r.name.toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr')));if(limit)rr=rr.slice(0,limit);return `<section class="panel"><div class="panel-head"><div><h2>Aylık ödemeler</h2><small>${monthLabel(month)} · Vade sırasına göre</small></div><div class="tabs">${[['all','Tümü'],['unpaid','Bekleyen'],['paid','Ödenen']].map(([v,t])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${t}</button>`).join('')}</div></div>${!limit?'<div class="toolbar"><input class="search" id="expense-search" placeholder="Ödeme ara…" aria-label="Ödeme ara"></div>':''}<div class="table-label"><span>ÖDEME ADI</span><span>SON ÖDEME</span><span>TUTAR</span></div><div id="expense-list">${state.records.length?expenseRows(rr):empty()}</div>${limit?`<div class="panel-pad" style="padding-top:14px"><button class="text-btn" data-view="payments">Tüm ${s.count} ödemeyi gör →</button></div>`:''}<div class="table-footer"><div>Kalan ödeme<small>${money(s.paid)} ödendi · ${s.done}/${s.count} tamamlandı</small></div><strong>${money(s.remaining)}</strong></div></section>`}
function planCard(s){const r=priorities(state,month)[0];return `<section class="plan-card"><div class="plan-title"><span class="eyebrow" style="margin:0;color:#7a8b68">PUSULA AKILLI PLAN</span><span class="spark">${icon('spark')}</span></div><h2>${s.baseGap<0?'Bu ay önceliklere<br>yer açalım.':'Bir adım önde olun.'}</h2><p>${s.baseGap<0?`Gelir bütçeniz, giderlerinizin ${Math.round(s.base/s.total*100)}%’ini karşılıyor. Vadesi gelen ve zorunlu ödemelerle başlayın.`:'Ödeme takviminizi takip edin; gelecek ayın giderlerini bugünden görün.'}${r?`<br><b>İlk sırada: ${esc(r.name)}</b>`:''}</p><button class="primary" data-view="plan">Ödeme planımı göster ${icon('arrow')}</button><small style="display:block;margin-top:11px;font-size:9px">Vade ve zorunluluk temelli otomatik sıralama.</small></section>`}
function chart(){const mm=months(month,6),ss=mm.map(m=>summary(state,m)),max=Math.max(...ss.map(s=>s.total),state.income,1);return `<section class="panel"><div class="panel-head"><div><h2>Nakit akışına bir bakış</h2><small>Önümüzdeki 6 ay · planlanan</small></div>${icon('chart').replace('<svg','<svg style="width:20px;color:#849279"')}</div><div class="chart-wrap">${mm.map((m,i)=>`<div class="chart-col"><div class="bars"><i style="height:${Math.max(3,ss[i].base/max*100)}%" title="Gelir: ${money(ss[i].base)}"></i><i style="height:${Math.max(3,ss[i].total/max*100)}%" title="Gider: ${money(ss[i].total)}"></i></div><small>${monthLabel(m).split(' ')[0].slice(0,3)}</small></div>`).join('')}</div><div class="legend"><span><i></i>Gelir bütçesi</span><span><i class="light"></i>Planlanan gider</span></div></section>`}
function balances(){const d=debtRows(state,month),card=d.filter(x=>x.type==='Kart').reduce((a,x)=>a+(x.remaining||0),0),loan=d.filter(x=>x.type==='Kredi').reduce((a,x)=>a+(x.remaining||0),0);return `<section class="panel"><div class="panel-head"><h2>Borç görünümü</h2><button class="text-btn" data-view="debts">Detaylar ↗</button></div><div class="balance-top"><small>Kalan bilinen borç · ${monthLabel(month)}</small><div class="metric">${money(card+loan)}</div><div class="allocation"><i style="width:${card/Math.max(1,card+loan)*100}%"></i><i style="flex:1"></i></div><div class="row"><small>Kartlar ${money(card)}</small><small>Krediler ${money(loan)}</small></div><p class="footnote">Krediler kalan taksit toplamıdır. Eminevim ve başlangıç bakiyesi bilinmeyen kartlar dahil değildir.</p></div></section>`}
function upcoming(){const r=priorities(state,month).slice(0,3);return `<section class="panel"><div class="panel-head"><h2>Önce bunlara bakın</h2><span class="pill">${r.length} ödeme</span></div>${r.map(x=>`<div class="mini-row"><span class="day">${x.day||'—'}</span><div><strong>${esc(x.name)}</strong><small>${x.reason}</small></div><span class="amount">${money(x.remaining)}</span></div>`).join('')||'<div class="panel-pad sub">Bekleyen ödeme yok.</div>'}<div style="height:10px"></div></section>`}
function overview(s){return `${stats(s)}${s.baseGap<0?`<div class="alert-inline">${icon('alert')}<span><strong>${money(-s.baseGap)} bütçe açığı var.</strong> ${s.expected?`Beklenen ${money(s.expected)} alacağınız tahsil edilirse fark ${money(s.gap)} olur. Alacaklar henüz gelir sayılmaz.`:'Giderler gelir bütçenizi aşıyor. Ödeme planınızı ve gelirlerinizi gözden geçirin.'}</span></div>`:''}<div class="content-grid"><div class="stack" style="display:flex">${expensePanel(s)}${chart()}</div><aside class="stack">${planCard(s)}${upcoming()}${balances()}</aside></div>`}
function calendar(){const [y,m]=month.split('-').map(Number),len=new Date(y,m,0).getDate(),offset=(new Date(y,m-1,1).getDay()+6)%7,rr=rows(state,month);return `<section class="panel"><div class="panel-head"><h2>Ödeme takvimi</h2><small>${monthLabel(month)}</small></div><div class="calendar">${['Pt','Sa','Ça','Pe','Cu','Ct','Pa'].map(x=>`<div class="cal-head">${x}</div>`).join('')}${'<div class="cal-day empty"></div>'.repeat(offset)}${Array.from({length:len},(_,i)=>{const a=rr.filter(r=>r.date===month+'-'+String(i+1).padStart(2,'0'));return `<div class="cal-day ${a.length?'has':''} ${today()===month+'-'+String(i+1).padStart(2,'0')?'today':''}" title="${a.map(r=>esc(r.name)).join(', ')}">${i+1}${a.length?`<b>${a.length} ödeme</b>`:''}</div>`}).join('')}</div></section>`}
function incomePanel(s){return `<section class="panel"><div class="panel-head"><div><h2>Gelir & alacaklar</h2><small>Aylık gelir bütçesi: ${money(s.base)}</small></div><button class="text-btn" data-action="new-income">+ Ekle</button></div>${incomeRows(state,month).map(r=>`<div class="income-row"><button class="check ${r.paid?'checked':''}" role="checkbox" aria-checked="${!!r.paid}" aria-label="${esc(r.name)} tahsil edildi" data-receive="${r.id}">${r.paid?icon('check'):''}</button><div><strong style="font-size:12px">${esc(r.name)}</strong><small style="display:block">${r.paid?'Tahsil edildi':'Tahsilat bekliyor'}${r.recurring?' · Her ay':''}${r.day?' · Ayın '+r.day+"’i":''}</small></div><span class="amount">${money(r.amount)}</span><button class="more" data-income-edit="${r.id}" aria-label="Geliri düzenle">Düzenle</button></div>`).join('')||'<div class="panel-pad sub">Bu ay ek gelir veya alacak yok.</div>'}<div class="table-footer"><span>Tahsil edilen ek gelir</span><b>${money(s.received)}</b></div></section>`}
function payments(s){return `${stats(s)}<div class="content-grid"><div>${expensePanel(s)}</div><aside class="stack">${calendar()}${incomePanel(s)}</aside></div>`}
function debts(){const ds=debtRows(state,month);return `<div class="alert-inline">${icon('shield')}<span>Seçili aya kadar işaretlediğiniz ödemeler düşülür. Kredi tutarı anapara değil, kalan taksit toplamıdır. Kartlara yeni harcama/faiz eklemeyi unutmayın.</span></div><div class="section-grid">${ds.map(d=>`<section class="panel debt-card"><div class="row"><span class="pill">${esc(d.type)}</span><button class="text-btn" data-debt="${d.id}">Düzenle ↗</button></div><div class="debt-brand">${brandLogo(d)}</div><h2 style="margin-top:14px">${esc(d.name)}</h2><div class="metric">${d.remaining===null?'Bakiye girilmedi':money(d.remaining)}</div><div class="progress"><i style="width:${Math.min(100,d.paid/Math.max(1,(d.initial||0)+(d.added||0))*100)}%"></i></div><footer><span>${money(d.paid)} ödendi</span><span>Başlangıç ${d.initial===null?'bilinmiyor':money(d.initial)}</span></footer>${d.overpaid?`<p class="footnote">Bakiyeyi aşan ödeme: ${money(d.overpaid)}</p>`:''}</section>`).join('')||empty()}</div><p class="footnote">Eminevim araç ve ev için kalan taksit sayısı / borç bildirilmedi. Bu ödemeler aylık listede yer alır, bilinen toplam borca eklenmez.</p>`}
function plan(s){const list=priorities(state,month);let budget=Math.max(0,s.base+s.received-s.paid);return `<div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Ödeme öncelikleriniz</h2><small>Vade, zorunluluk ve ödeme türüne göre</small></div><span class="pill">Otomatik plan</span></div><div class="panel-pad"><div class="note" style="margin:0">Bu sıralama yapay zekâ çıktısı değildir. Faiz, bankanın asgari tutarı ve gecikme koşulları bilinmediği için kesin bir borç kapatma önerisi vermez.</div></div><div class="priority-list">${list.map((r,i)=>{const fits=budget>=r.remaining;budget-=r.remaining;return `<div class="priority-item"><span class="rank">${i+1}</span><div style="flex:1"><h3>${esc(r.name)}</h3><div class="reason">${r.reason}</div><small>${fits?'Gelir bütçesine sığıyor':'Ek kaynak gerektiriyor'}</small></div><span class="amount">${money(r.remaining)}</span><button class="check" data-pay="${r.id}" aria-label="${esc(r.name)} ödendi" role="checkbox" aria-checked="false"></button></div>`}).join('')||'<p class="sub">Bekleyen ödeme yok.</p>'}</div></section><aside class="stack"><section class="panel settings"><div class="row"><h2>Gelir senaryosu</h2><span class="spark">${icon('chart')}</span></div><p style="margin-top:14px">Bu ayın gelir bütçesini değiştirerek farkı görün. Alacaklar ayrı tutulur.</p><div class="metric" id="scenario-value">${money(s.base)}</div><input class="scenario" id="scenario" type="range" min="100000" max="250000" step="5000" value="${s.base}" aria-label="Gelir senaryosu"><div class="scenario-label"><span>100.000 ₺</span><span>250.000 ₺</span></div><div class="note" id="scenario-gap">Gider sonrası fark: ${money(s.baseGap)}</div></section><section class="plan-card"><div class="row"><h2 style="margin:0">Yapay zekâ yorumu</h2><span class="spark">${icon('spark')}</span></div><p style="margin-top:15px">${aiAvailable?'Seçili ayın gelir, vade ve ödeme bilgilerini analiz ederek bir açıklama üretir.':'Güvenli yapay zekâ bağlantısı henüz etkin değil. Otomatik ödeme planınız çalışmaya devam eder.'}</p>${aiAvailable?'<button class="primary" data-action="ai">Bu ayı analiz et →</button><small style="display:block;margin-top:10px">Seçili ayın ödeme bilgileri analiz için OpenAI’a gönderilir.</small>':'<span class="pill" style="display:inline-block;margin-top:15px">Bağlantı bekleniyor</span>'}${aiText?`<div class="ai-result">${esc(aiText)}</div>`:''}</section></aside></div>`}
function reports(){const mm=months('2026-11',19);return `${chart()}<section class="panel" style="margin-top:22px"><div class="panel-head"><div><h2>Aylık finans tablosu</h2><small>Kasım 2026 – Mayıs 2028 · Kredi taksit dönemi</small></div><button class="secondary" data-action="csv">CSV indir</button></div><div class="scroll"><table class="report-table"><thead><tr><th>Ay</th><th>Gelir bütçesi</th><th>Gider</th><th>Ödenen</th><th>Kalan ödeme</th><th>Kalan bilinen borç</th></tr></thead><tbody>${mm.map(m=>{const s=summary(state,m),debt=debtRows(state,m).reduce((a,d)=>a+(d.remaining||0),0);return `<tr><td><button class="text-btn" data-month="${m}">${monthLabel(m)}</button></td><td>${money(s.base)}</td><td>${money(s.total)}</td><td>${money(s.paid)}</td><td>${money(s.remaining)}</td><td>${money(debt)}</td></tr>`}).join('')}</tbody></table></div><div class="panel-pad"><p class="footnote">Borç sütunu, ilgili aya kadar gerçekten işaretlenmiş ödemeleri düşer. Gelecekteki planlanan ödemeler yapılmış sayılmaz.</p></div></section>`}
function settings(){return `<div class="button-group" style="margin-bottom:20px"><button class="secondary" data-view="reports">Aylık raporlar</button><button class="secondary" data-view="payments">Gelir ve giderleri yönet</button></div><div class="section-grid"><section class="panel settings"><h2>Gelir bütçem</h2><p style="margin-top:12px">Varsayılan aylık geliriniz ve gelir aralığınız. Aylık gerçekleşen gelir yerine planlama bütçesidir.</p><div class="metric">${money(state.income)}</div><p>${money(state.incomeLow)} – ${money(state.incomeHigh)}</p><button class="primary" data-action="income">Gelirimi düzenle</button></section><section class="panel settings"><h2>Yedekleme & geri yükleme</h2><p style="margin-top:12px">Kayıtlar bu tarayıcıda saklanır. Safari verilerini silerseniz veya cihaz değiştirirseniz geri yüklemek için yedek dosyanız gerekir. Otomatik bulut eşitlemesi yoktur.</p><div class="button-group"><button class="primary" data-action="export">${icon('down')} Yedek indir</button><button class="secondary" data-action="import">Yedeği yükle</button></div><p class="footnote">Yedek dosyası finansal bilgilerinizi içerir. Kişisel dosyalarınızda saklayın.</p></section><section class="panel settings"><h2>iPhone’da uygulama gibi kullanın</h2><p style="margin-top:12px">Bu adresi Safari’de açın. Paylaş menüsünden “Ana Ekrana Ekle” seçeneğini kullanın. Pusula simgesiyle uygulamaya ulaşabilirsiniz.</p><div class="note">Bu sürüm bir web uygulamasıdır. Bildirim ve banka hesabına bağlantı içermez.</div></section><section class="panel settings"><h2>Akıllı plan & gizlilik</h2><p style="margin-top:12px">Vade ve zorunlu giderlere göre otomatik öncelik sıralaması cihazınızda hesaplanır. Yapay zekâ yorumu yalnızca düğmeye bastığınızda, güvenli bağlantı etkinse çalışır.</p><span class="pill">${aiAvailable?'Yapay zekâ bağlantısı etkin':'Yapay zekâ bağlantısı bekleniyor'}</span><p class="footnote">API anahtarları bu uygulamanın içine veya GitHub koduna yazılmaz.</p></section></div>`}
function modal(title,html){$('#modal').innerHTML=`<div class="modal-head"><h2>${title}</h2><button data-close aria-label="Kapat">${icon('close').replace('<svg','<svg style="width:22px"')}</button></div><div class="modal-body">${html}</div>`;$('#modal').showModal()}
const field=(label,name,value='',type='text',wide=false,attrs='')=>`<label class="field ${wide?'wide':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
function editModal(id){const r=id?rows(state,month).find(x=>x.id===id):null;modal(r?'Ödemeyi düzenle':'Yeni ödeme',`<form id="payment-form" data-id="${id||''}"><div class="form-grid">${field('Gider adı','name',r?.name||'','text',true,'required maxlength="100"')}${field('Aylık tutar (₺)','amount',r?.amount??'','number',false,'required min="0" max="999999999" step="0.01"')}${field('Ödeme günü (boş = tarihsiz)','day',r?.day||'','number',false,'min="1" max="31" step="1"')}<label class="field wide">Banka / kurum<select name="bank">${bankOptions(r?.bank||detectBank(r?.name||''))}</select></label><label class="field">Tür<select name="type">${['Yaşam','Kredi','Kart','Eminevim','Diğer'].map(t=>`<option ${r?.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Zorunlu yaşam gideri<select name="essential"><option value="false">Hayır</option><option value="true" ${r?.essential?'selected':''}>Evet</option></select></label>${!r?`${field('Başlangıç ayı','start',month,'month',false,'required')}${field('Kaç ay? (0 = her ay)','count',0,'number',false,'min="0" max="600" step="1"')}${field('Kart başlangıç borcu (biliniyorsa)','initial','','number',true,'min="0" step="0.01"')}`:`<label class="field wide">Değişiklik kapsamı<select name="scope"><option value="month">Sadece ${monthLabel(month)}</option><option value="future">Bu ay ve sonraki aylar</option></select></label>${field('Bu ay ödediğim tutar (₺)','paid',r.paid,'number',true,'min="0" step="0.01"')}`}</div><div class="note">${r?'Geçmiş aylardaki kayıtlarınız değişmez. Ödendi düğmesi tam ödeme içindir; kısmi ödemeyi buraya yazabilirsiniz.':'Her ay otomatik tekrar eder. Kredi için taksit sayısı girerseniz son taksitten sonra durur.'}</div><div class="modal-actions">${r?`<button type="button" class="secondary danger" data-delete-expense="${r.id}">Ödemeyi sil</button>`:''}<button type="submit" class="primary">Kaydet</button></div></form>`)}
function incomeModal(){modal('Gelir bütçesini düzenle',`<form id="budget-form"><div class="form-grid">${field('Bu ayın gelir bütçesi (₺)','monthly',summary(state,month).base,'number',true,'required min="0" step="1000"')}${field('Varsayılan aylık gelir (₺)','income',state.income,'number',true,'required min="0" step="1000"')}${field('Alt sınır (₺)','low',state.incomeLow,'number',false,'required min="0"')}${field('Üst sınır (₺)','high',state.incomeHigh,'number',false,'required min="0"')}</div><div class="modal-actions"><button class="primary">Kaydet</button></div></form>`)}
function receiveModal(id){const r=incomeRows(state,month).find(x=>x.id===id);modal(r?'Geliri düzenle':'Gelir ekle',`<form id="receive-form" data-id="${id||''}"><div class="form-grid">${field('Gelir adı / kaynak','name',r?.name||'','text',true,'required maxlength="100"')}${field('Tutar (₺)','amount',r?.amount??'','number',false,'required min="0" step="0.01"')}${field('Gelir günü (boş = belirsiz)','day',r?.day||'','number',false,'min="1" max="31" step="1"')}${!r?`<label class="field wide">Tekrar<select name="recurring"><option value="yes">Her ay tekrarlansın</option><option value="no">Sadece bu ay</option></select></label>${field('Başlangıç ayı','start',month,'month',false,'required')}${field('Kaç ay? (0 = sürekli)','count',0,'number',false,'min="0" max="600" step="1"')}`:r.recurring?`<label class="field wide">Değişiklik kapsamı<select name="scope"><option value="month">Sadece bu ay</option><option value="future">Bu ay ve sonraki aylar</option></select></label>`:''}</div><div class="note">Bu kalem, aylık gelir bütçenize ek gelir olarak gösterilir. Aynı geliri iki yerde saymamak için bütçenizi buna göre düzenleyin.</div><div class="modal-actions">${r?`<button type="button" class="secondary danger" data-remove-income="${id}">Geliri sil</button>`:''}<button class="primary">Kaydet</button></div></form>`)}
function deleteModal(id,isIncome){modal(isIncome?'Geliri sil':'Ödemeyi sil',`<p class="sub">Silme kapsamını seçin. Kaydedilmiş borç ödeme geçmişi korunur.</p><label class="field" style="margin-top:18px">Kapsam<select id="delete-scope"><option value="month">Yalnızca bu aydan kaldır</option><option value="future">Bu ay ve sonraki aylardan kaldır</option><option value="all">Bütün aylardan kaldır</option></select></label><div class="modal-actions"><button class="secondary" data-close>Vazgeç</button><button class="primary" id="confirm-delete">Sil</button></div>`);$('#confirm-delete').onclick=()=>{const snapshot=JSON.stringify(state),scope=$('#delete-scope').value;if(isIncome)deleteIncome(state,month,id,scope);else deleteExpense(state,month,id,scope);save(false);$('#modal').close();render();toast('Kayıt silindi.');const undo=document.createElement('button');undo.textContent='Geri al';undo.style.cssText='margin-left:16px;text-decoration:underline;color:white';undo.onclick=()=>{state=JSON.parse(snapshot);save(false);render();toast('Silme geri alındı')};$('#toast').append(undo);$('#toast').style.pointerEvents='auto';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>{$('#toast').classList.remove('visible');$('#toast').style.pointerEvents='none'},12000)}}

function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}
async function importFile(){const inp=document.createElement('input');inp.type='file';inp.accept='.json,application/json';inp.onchange=async()=>{try{const f=inp.files[0];if(!f)return;if(f.size>2000000)throw Error('Yedek 2 MB sınırını aşıyor.');const next=validate(JSON.parse(await f.text()));modal('Yedeği geri yükle',`<p class="sub">Bu dosyada ${next.records.length} ödeme var. Mevcut kayıtlarınız değiştirilecek. Önce yedeğinizi indirmeniz önerilir.</p><div class="modal-actions"><button class="secondary" data-action="export">Mevcut yedeği indir</button><button class="primary" id="confirm-import">Geri yükle</button></div>`);$('#confirm-import').onclick=()=>{state=next;save();$('#modal').close();render()}}catch(e){toast(e.message)}};inp.click()}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
if(d.close!==undefined){$('#modal').close();return}if(d.view){view=d.view;search='';filter='all';render();window.scrollTo(0,0);return}if(d.month){month=d.month;aiText='';render();return}if(d.filter){filter=d.filter;render();return}
if(d.pay){const r=rows(state,month).find(x=>x.id===d.pay);pay(state,month,d.pay,r.isPaid?0:r.amount);save(false);render();toast(r.isPaid?'Ödeme işareti kaldırıldı':r.name+' ödendi');return}
if(d.edit!==undefined){editModal(d.edit);return}if(d.receive){const r=incomeRows(state,month).find(x=>x.id===d.receive);const paid=!r.paid;if(r.recurring){state.incomePaid??={};state.incomePaid[month+'|'+r.id]=paid}else state.receivables.find(x=>x.id===r.id).paid=paid;save(false);render();toast(paid?'Tahsilat kaydedildi':'Tahsilat geri alındı');return}if(d.incomeEdit){receiveModal(d.incomeEdit);return}
if(d.removeIncome){deleteModal(d.removeIncome,true);return}if(d.deleteExpense){deleteModal(d.deleteExpense,false);return}
if(d.debt){const r=state.debts.find(x=>x.id===d.debt);modal('Borç bilgisini düzenle',`<form id="debt-form" data-id="${r.id}"><p class="sub" style="margin-bottom:18px">${esc(r.name)} · Ödemeleriniz otomatik düşülür.</p><div class="form-grid">${field('Başlangıç borcu (bilinmiyorsa boş)','initial',r.initial??'','number',true,'min="0" step="0.01"')}${field('Ek harcama / faiz toplamı','added',r.added||0,'number',true,'min="0" required step="0.01"')}</div><div class="modal-actions"><button class="primary">Kaydet</button></div></form>`);return}
if(d.stop){const id=d.stop;modal('Tekrarlanan ödemeyi durdur',`<p class="sub">${monthLabel(month)} sonrasındaki yeni aylarda bu gider oluşmayacak. Bu ay ve geçmiş ödemeler korunur.</p><div class="modal-actions"><button class="secondary" data-close>Vazgeç</button><button class="primary" id="confirm-stop">Tekrarı durdur</button></div>`);$('#confirm-stop').onclick=()=>{edit(state,addMonths(month,1),id,{disabled:true},'future');save();$('#modal').close();render()};return}
if(d.action==='new'){editModal();return}if(d.action==='income'){incomeModal();return}if(d.action==='new-income'){receiveModal();return}if(d.action==='export'){download('Pusula-Yedek-'+today()+'.json',JSON.stringify(state,null,2));toast('Yedek dosyası hazır');return}if(d.action==='import'){importFile();return}if(d.action==='csv'){const data=[['Ay','Gelir bütçesi','Gider','Ödenen','Kalan','Bilinen borç'],...months('2026-11',19).map(m=>{const s=summary(state,m);return [monthLabel(m),s.base,s.total,s.paid,s.remaining,debtRows(state,m).reduce((a,x)=>a+(x.remaining||0),0)]})];download('Pusula-Rapor.csv','\ufeff'+data.map(r=>r.join(';')).join('\r\n'),'text/csv;charset=utf-8');return}
if(d.action==='ai'){b.disabled=true;b.textContent='Analiz hazırlanıyor…';try{const payload={month,summary:summary(state,month),payments:priorities(state,month).map(r=>({name:r.name,type:r.type,amount:r.amount,remaining:r.remaining,due:r.date,reason:r.reason})),incomeRange:[state.incomeLow,state.incomeHigh]};const r=await fetch('./api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const v=await r.json();if(!r.ok)throw Error(v.error||'Analiz şu anda alınamadı.');aiText=v.text;render()}catch(e){toast(e.message);b.disabled=false;b.textContent='Yeniden dene'}return}
});
document.addEventListener('submit',e=>{if(!e.target.matches('#payment-form,#budget-form,#receive-form,#debt-form'))return;e.preventDefault();const before=JSON.stringify(state),form=e.target,f=Object.fromEntries(new FormData(form));try{if(form.id==='payment-form'){const values={name:f.name.trim(),amount:Number(f.amount),day:Number(f.day)||0,type:f.type,bank:f.bank||'',essential:f.essential==='true'};if(!values.name)throw Error('Gider adı girin.');const id=form.dataset.id;if(id){edit(state,month,id,values,f.scope);pay(state,month,id,Number(f.paid))}else{const id=crypto.randomUUID(),count=Number(f.count);state.records.push({id,start:f.start,count,versions:[{from:f.start,...values}]});if(f.type==='Kredi'||f.type==='Kart')state.debts.push({id:crypto.randomUUID(),recordId:id,name:values.name,type:f.type,initial:f.type==='Kredi'?(count?values.amount*count:null):(f.initial===''?null:Number(f.initial)),added:0})}}
if(form.id==='budget-form'){if(Number(f.low)>Number(f.high))throw Error('Alt sınır üst sınırdan büyük olamaz.');state.monthlyIncome[month]=Number(f.monthly);state.income=Number(f.income);state.incomeLow=Number(f.low);state.incomeHigh=Number(f.high)}
if(form.id==='receive-form'){const id=form.dataset.id,values={name:f.name.trim(),amount:Number(f.amount),day:Number(f.day)||0};if(!values.name)throw Error('Gelir adını girin.');if(id){if((state.incomeRules||[]).some(r=>r.id===id))editIncome(state,month,id,values,f.scope);else Object.assign(state.receivables.find(r=>r.id===id),values)}else if(f.recurring==='yes'){state.incomeRules??=[];state.incomeRules.push({id:crypto.randomUUID(),start:f.start,count:Number(f.count),versions:[{from:f.start,...values}]})}else state.receivables.push({id:crypto.randomUUID(),month,...values,paid:false})}

if(form.id==='debt-form'){const r=state.debts.find(x=>x.id===form.dataset.id);r.initial=f.initial===''?null:Number(f.initial);r.added=Number(f.added)}validate(state);save();$('#modal').close();render()}catch(err){state=JSON.parse(before);toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='expense-search'){search=e.target.value;const rr=rows(state,month).filter(r=>(filter==='all'||(filter==='paid'?r.isPaid:!r.isPaid))&&r.name.toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr')));$('#expense-list').innerHTML=expenseRows(rr)}if(e.target.id==='scenario'){const value=Number(e.target.value);$('#scenario-value').textContent=money(value);$('#scenario-gap').textContent='Gider sonrası fark: '+money(value-summary(state,month).total)}});
document.addEventListener('change',e=>{if(e.target.id==='scenario'){state.monthlyIncome[month]=Number(e.target.value);save(false);render()}});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=validate(JSON.parse(e.newValue));render();toast('Diğer sekmedeki değişiklikler alındı')}catch{}}});
render();

function detectBank(name){const n=name.toLocaleLowerCase('tr');if(n.includes('garanti'))return 'garanti';if(n.includes('akbank')||n.includes('wings'))return 'akbank';if(n.includes('fibabanka'))return 'fibabanka';if(n.includes('işbank')||n.includes('iş bankası'))return 'isbank';if(n.includes('eminevim'))return 'eminevim';return Object.entries(banks).find(([id,label])=>n.includes(label.toLocaleLowerCase('tr')))?.[0]||''}
function bankOptions(selected){return '<option value="">Kurum seçilmedi</option>'+Object.entries(banks).sort((a,b)=>a[1].localeCompare(b[1],'tr')).map(([id,label])=>`<option value="${id}" ${selected===id?'selected':''}>${label}</option>`).join('')}
function brandLogo(record){const id=record.bank||detectBank(record.name||'');return banks[id]?`<img class="bank-logo" src="logos/${id}.svg" alt="${esc(banks[id])}" loading="lazy">`:icon(record.type==='Kart'?'card':record.essential?'home':'wallet')}
